namespace RecipeHub.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string CategorySlug { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = new();
    public List<string> Steps { get; set; } = new();
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();

    public RecipeService()
    {
        _recipes = new List<Recipe>
        {
            new Recipe
            {
                Id = 1,
                Title = "Bruschetta",
                Category = "Appetizers",
                CategorySlug = "appetizers",
                Ingredients = new() { "Baguette", "Tomatoes", "Fresh basil", "Garlic", "Olive oil", "Balsamic vinegar" },
                Steps = new() { "Slice baguette and toast until golden.", "Dice tomatoes and mix with chopped basil, minced garlic, and olive oil.", "Spoon tomato mixture onto toasted bread.", "Drizzle with balsamic vinegar and serve." },
                AverageRating = 4.5,
                RatingCount = 12
            },
            new Recipe
            {
                Id = 2,
                Title = "Stuffed Mushrooms",
                Category = "Appetizers",
                CategorySlug = "appetizers",
                Ingredients = new() { "Button mushrooms", "Cream cheese", "Garlic", "Parmesan", "Breadcrumbs", "Parsley" },
                Steps = new() { "Remove stems from mushrooms and hollow out caps.", "Mix cream cheese, minced garlic, parmesan, and breadcrumbs.", "Fill mushroom caps with the mixture.", "Bake at 375°F for 20 minutes until golden." },
                AverageRating = 4.2,
                RatingCount = 8
            },
            new Recipe
            {
                Id = 3,
                Title = "Spaghetti Carbonara",
                Category = "Main Courses",
                CategorySlug = "main-courses",
                Ingredients = new() { "Spaghetti", "Pancetta", "Eggs", "Parmesan cheese", "Black pepper", "Salt" },
                Steps = new() { "Cook spaghetti in salted boiling water until al dente.", "Fry pancetta until crispy.", "Whisk eggs with grated parmesan and pepper.", "Toss hot pasta with pancetta, then quickly stir in egg mixture off heat.", "Serve immediately with extra parmesan." },
                AverageRating = 4.8,
                RatingCount = 25
            },
            new Recipe
            {
                Id = 4,
                Title = "Chicken Tikka Masala",
                Category = "Main Courses",
                CategorySlug = "main-courses",
                Ingredients = new() { "Chicken breast", "Yogurt", "Tikka spice mix", "Onion", "Tomato sauce", "Heavy cream", "Rice" },
                Steps = new() { "Marinate chicken in yogurt and spices for 2 hours.", "Grill or pan-fry chicken until charred.", "Sauté onions, add tomato sauce and cream.", "Add chicken to sauce and simmer 15 minutes.", "Serve over basmati rice." },
                AverageRating = 4.7,
                RatingCount = 18
            },
            new Recipe
            {
                Id = 5,
                Title = "Chocolate Lava Cake",
                Category = "Desserts",
                CategorySlug = "desserts",
                Ingredients = new() { "Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract" },
                Steps = new() { "Melt chocolate and butter together.", "Whisk eggs and sugar until fluffy.", "Fold chocolate mixture into eggs, add flour and vanilla.", "Pour into greased ramekins.", "Bake at 425°F for 12 minutes. Center should be soft.", "Invert onto plates and serve immediately." },
                AverageRating = 4.9,
                RatingCount = 30
            },
            new Recipe
            {
                Id = 6,
                Title = "Mango Smoothie",
                Category = "Beverages",
                CategorySlug = "beverages",
                Ingredients = new() { "Mango", "Banana", "Yogurt", "Honey", "Ice" },
                Steps = new() { "Peel and chop mango and banana.", "Blend fruits with yogurt, honey, and ice.", "Pour into glasses and serve cold." },
                AverageRating = 4.3,
                RatingCount = 10
            },
            new Recipe
            {
                Id = 7,
                Title = "Sourdough Bread",
                Category = "Breads",
                CategorySlug = "breads",
                Ingredients = new() { "Bread flour", "Sourdough starter", "Water", "Salt" },
                Steps = new() { "Mix flour, starter, and water. Rest 30 minutes.", "Add salt and fold dough every 30 minutes for 2 hours.", "Shape and place in banneton. Cold proof overnight.", "Bake in Dutch oven at 450°F for 40 minutes." },
                AverageRating = 4.6,
                RatingCount = 14
            },
            new Recipe
            {
                Id = 8,
                Title = "Caesar Salad",
                Category = "Salads",
                CategorySlug = "salads",
                Ingredients = new() { "Romaine lettuce", "Croutons", "Parmesan", "Caesar dressing", "Lemon", "Anchovies" },
                Steps = new() { "Wash and chop romaine lettuce.", "Make dressing: blend anchovies, lemon juice, garlic, and olive oil.", "Toss lettuce with dressing.", "Top with croutons and shaved parmesan." },
                AverageRating = 4.1,
                RatingCount = 9
            }
        };
    }

    public List<Recipe> GetAll() => _recipes;

    public List<Recipe> GetByCategory(string categorySlug) =>
        _recipes.Where(r => r.CategorySlug == categorySlug).ToList();

    public Recipe? GetById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().ToList();

    public Dictionary<string, string> GetCategorySlugs() =>
        _recipes.GroupBy(r => r.CategorySlug)
                .ToDictionary(g => g.Key, g => g.First().Category);

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = GetById(recipeId);
        if (recipe == null || stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var allRatings = _ratings[recipeId];
        recipe.AverageRating = Math.Round(allRatings.Average(), 1);
        recipe.RatingCount = allRatings.Count;
    }
}

